#!/usr/bin/env python3
"""Convert binary Windows Event Log (.evtx) files to a Vestigo Parquet file.

Parses the *binary* EVTX container directly — a single file or a directory of them (a
triage collection is routinely 50-200 files). For *text* exports (wevtutil XML,
evtx_dump XML/JSONL) use evtx2timesketch.py instead.

Forensic provenance embedded in the output:
  - per input file: name, absolute path, sha256, size, mtime
  - per event row: byte offset of the record *inside the original .evtx*, and the sha256
    of that record's raw bytes — so `dd bs=1 skip=<byte_offset> count=<record_size>`
    against the original file reproduces `content_hash` with no Vestigo tooling
  - converter name + version, and the EvtxECmd map corpus commit the messages came from

Recovery: each 64 KiB chunk is parsed in isolation, so one corrupt chunk costs only that
chunk. Parsing a file as a whole (the obvious approach) makes the underlying parser abort
permanently at the first bad chunk header — on real evidence that silently drops every
record after the damage.

Not resolved: `%%1833`-style message-table references stay as-is; rendering them needs the
provider's WEVT templates from the originating host, which a converter does not have.

Requires pyarrow and evtx:
    pip install pyarrow evtx
    uv run --with pyarrow --with evtx evtx2vestigo.py ...

Usage:
    evtx2vestigo.py -i Security.evtx -o security.parquet
    evtx2vestigo.py -i C:/triage/winevt/Logs/ -o logs.parquet -w 8
"""

from __future__ import annotations

import argparse
import base64
import collections
import concurrent.futures
import contextlib
import datetime
import hashlib
import io
import ipaddress
import json
import mmap
import multiprocessing
import os
import re
import struct
import sys
import xml.etree.ElementTree as ET
import zlib
from pathlib import Path
from typing import Any

try:
    import pyarrow as pa
    import pyarrow.parquet as pq
except ImportError:  # pragma: no cover - environment guard
    sys.stderr.write(
        "error: pyarrow is required to write Vestigo Parquet files.\n"
        "Install it with:  pip install pyarrow\n"
        "or run this script via:  uv run --with pyarrow --with evtx evtx2vestigo.py ...\n"
    )
    sys.exit(2)

try:
    from evtx import PyEvtxParser
except ImportError:  # pragma: no cover - environment guard
    sys.stderr.write(
        "error: the 'evtx' package is required to parse binary .evtx files.\n"
        "Install it with:  pip install evtx\n"
        "or run this script via:  uv run --with pyarrow --with evtx evtx2vestigo.py ...\n"
        "For *text* exports (wevtutil XML, evtx_dump XML/JSONL) use evtx2timesketch.py.\n"
    )
    sys.exit(2)

CONVERTER_NAME = "evtx2vestigo"
CONVERTER_VERSION = "1.0.0"

# ---------------------------------------------------------------------------
# Vestigo Parquet interchange format v1 — embedded copy of the spec in
# src/vestigo/ingestion/parquet_format.py (this script is a standalone
# download and cannot import it; the repo test suite asserts both stay equal).
# ---------------------------------------------------------------------------

FORMAT_VERSION = "1"
META_FORMAT_VERSION = "vestigo.format_version"
META_CONVERTER_NAME = "vestigo.converter_name"
META_CONVERTER_VERSION = "vestigo.converter_version"
META_ORIGINAL_FILES = "vestigo.original_files"
# Additive forensic footer metadata (Tier 1). Ignored by older readers.
META_CONVERTED_AT = "vestigo.converted_at"
META_ROW_COUNTS = "vestigo.row_counts"
META_TIMEZONE_ASSUMPTION = "vestigo.timezone_assumption"
META_PARSE_DECISIONS = "vestigo.parse_decisions"

PARQUET_EVENT_SCHEMA = pa.schema(
    [
        pa.field("source_file", pa.string()),
        pa.field("file_hash", pa.string()),
        pa.field("byte_offset", pa.uint64()),
        pa.field("content_hash", pa.string()),
        pa.field("message", pa.string()),
        pa.field("timestamp", pa.timestamp("ms", tz="UTC")),
        pa.field("timestamp_desc", pa.string()),
        pa.field("artifact", pa.string()),
        pa.field("artifact_long", pa.string()),
        pa.field("display_name", pa.string()),
        pa.field("tags", pa.list_(pa.string())),
        pa.field("attributes", pa.map_(pa.string(), pa.string())),
    ]
)

