# Attribute keys the Vestigo query layer resolves as top-level event columns; an
# attribute by one of these names would be unreachable from Sigma and the filter
# UI, so incoming field names that collide are prefixed.
_RESERVED_ATTR_KEYS = frozenset(
    {
        "message",
        "timestamp",
        "timestamp_desc",
        "artifact",
        "artifact_long",
        "display_name",
        "parser_name",
        "parser_version",
        "source_file",
        "source_id",
        "content_hash",
        "file_hash",
    }
)

# <System> children promoted to attributes, as (local name, attribute name).
# Spellings are Sigma-canonical: community Windows rules match `attributes`
# keys literally and case-sensitively, so `EventID` must be exactly that.
_SYSTEM_ATTRS = (
    ("EventID", "EventID"),
    ("Version", "Version"),
    ("Level", "Level"),
    ("Task", "Task"),
    ("Opcode", "Opcode"),
    ("Keywords", "Keywords"),
    ("EventRecordID", "EventRecordID"),
    ("Channel", "Channel"),
    ("Computer", "Computer"),
)

_BINARY_ATTR_LIMIT = 4096

# Characters XML 1.0 forbids outright. Windows writes raw control bytes into EventData
# (a policy value of \x03, say), which the parser faithfully renders into XML that no
# conformant parser will read back.
_RE_INVALID_XML_CHARS = re.compile(r"[^\x09\x0a\x0d\x20-퟿-�\U00010000-\U0010ffff]")

_XML_NS = "{http://schemas.microsoft.com/win/2004/08/events/event}"


class _Defaulting(dict):
    """format_map helper that renders missing template keys as ''."""

    def __missing__(self, key: str) -> str:
        return ""


def _local(tag: str) -> str:
    """Strip an XML namespace prefix from a tag name."""
    return tag.rsplit("}", 1)[-1]


def _safe_int(value: Any) -> int | None:
    if value is None or value == "":
        return None
    try:
        return int(value)
    except (ValueError, TypeError):
        return None


def normalize_ip(value: str | None) -> str:
    """Validate and canonicalize a single IPv4/IPv6 address string."""
    if not value:
        return ""
    try:
        return str(ipaddress.ip_address(value.strip().strip("[]")))
    except ValueError:
        return ""


def _safe_attr_key(name: str) -> str:
    """Rewrite an attribute key that would collide with a top-level event column."""
    return f"evt_{name}" if name.lower() in _RESERVED_ATTR_KEYS else name


def _parse_system_time(ts: str) -> datetime.datetime | None:
    """Parse a TimeCreated SystemTime value into a UTC-aware datetime.

    Windows emits 7-digit fractional seconds, which fromisoformat rejects on
    some Python versions; the fraction is trimmed to microseconds first.
    """
    if not ts:
        return None
    value = re.sub(r"(\.\d{6})\d+", r"\1", ts.strip()).replace("Z", "+00:00")
    try:
        dt = datetime.datetime.fromisoformat(value)
    except ValueError:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.UTC)
    return dt.astimezone(datetime.UTC)


def _parse_record_timestamp(ts: str) -> datetime.datetime | None:
    """Parse the parser's record-header timestamp (e.g. '2016-06-29T15:24:34.346Z UTC')."""
    if not ts:
        return None
    return _parse_system_time(ts.strip().removesuffix(" UTC"))


def _truncate_ms(dt: datetime.datetime | None) -> datetime.datetime | None:
    """Truncate to the interchange schema's millisecond resolution.

    Done explicitly rather than left to pyarrow's cast so the rounding behavior is the
    converter's documented decision; the untruncated original is kept verbatim in the
    TimeCreated_SystemTime attribute.
    """
    if dt is None:
        return None
    return dt.replace(microsecond=(dt.microsecond // 1000) * 1000)


def _extract_system(root: ET.Element) -> dict[str, str]:
    """Pull <System> into Sigma-canonical attribute names."""
    system = next((c for c in root if _local(c.tag) == "System"), None)
    if system is None:
        return {}
    children = {_local(c.tag): c for c in system}
    attrs: dict[str, str] = {}

    for tag, key in _SYSTEM_ATTRS:
        node = children.get(tag)
        if node is not None and node.text:
            attrs[key] = node.text.strip()

    # EventID compares as a string; never zero-pad it, or `EventID: 4624` stops matching.
    event_id = _safe_int(attrs.get("EventID"))
    if event_id is not None:
        attrs["EventID"] = str(event_id)
    qualifiers = children.get("EventID")
    if qualifiers is not None and qualifiers.get("Qualifiers"):
        attrs["Qualifiers"] = qualifiers.get("Qualifiers", "")

    provider = children.get("Provider")
    if provider is not None:
        if provider.get("Name"):
            attrs["Provider_Name"] = provider.get("Name", "")
        if provider.get("Guid"):
            attrs["Provider_Guid"] = provider.get("Guid", "")

    time_created = children.get("TimeCreated")
    if time_created is not None and time_created.get("SystemTime"):
        attrs["TimeCreated_SystemTime"] = time_created.get("SystemTime", "")

    execution = children.get("Execution")
    if execution is not None:
        # Prefixed so they cannot collide with Sysmon's EventData ProcessId/ThreadId.
        if execution.get("ProcessID"):
            attrs["Execution_ProcessID"] = execution.get("ProcessID", "")
        if execution.get("ThreadID"):
            attrs["Execution_ThreadID"] = execution.get("ThreadID", "")

    correlation = children.get("Correlation")
    if correlation is not None and correlation.get("ActivityID"):
        attrs["Correlation_ActivityID"] = correlation.get("ActivityID", "")

    security = children.get("Security")
    if security is not None and security.get("UserID"):
        attrs["SecurityUserID"] = security.get("UserID", "")

    return attrs


def _extract_event_data(root: ET.Element) -> dict[str, str]:
    """Pull <EventData>/<UserData> using the native Windows field names.

    Native names are exactly what community Sigma rules address, so they are kept
    verbatim rather than normalized into a house style.
    """
    attrs: dict[str, str] = {}
    for child in root:
        tag = _local(child.tag)
        if tag == "EventData":
            unnamed = 0
            for node in child:
                node_tag = _local(node.tag)
                if node_tag == "Data":
                    name = node.get("Name")
                    if not name:
                        unnamed += 1
                        name = f"Data{unnamed}"
                    if node.text:
                        attrs[name] = node.text
                elif node_tag == "Binary":
                    if node.text:
                        attrs["Binary"] = node.text[:_BINARY_ATTR_LIMIT]
                elif node.text:
                    attrs[node_tag] = node.text
        elif tag == "UserData":
            for container in child:
                prefix = f"UserData_{_local(container.tag)}"
                if container.text and container.text.strip():
                    attrs[prefix] = container.text.strip()
                for node in container.iter():
                    if node is container:
                        continue
                    if node.text and node.text.strip():
                        attrs[f"{prefix}_{_local(node.tag)}"] = node.text.strip()
    return attrs


def _channel_slug(channel: str) -> str:
    """Condense a channel name into an artifact-friendly slug."""
    slug = channel.strip().lower()
    slug = slug.removeprefix("microsoft-windows-")
    slug = re.sub(r"[\s/\\]+", "-", slug)
    return re.sub(r"[^a-z0-9._-]", "", slug) or "unknown"


def _artifact_for(channel: str, event_id: int | None) -> tuple[str, str]:
    """Return ``(artifact, timestamp_desc)`` for a record."""
    mapped = _EVENT_MAP.get(event_id) if event_id is not None else None
    if mapped and channel.strip().lower() == "security":
        return mapped[0], mapped[1]
    detail = str(event_id) if event_id is not None else "unknown"
    return f"winevtx:{_channel_slug(channel)}:{detail}", "Event Logged Time"


def _build_message(
    map_result: dict[str, str],
    event_id: int | None,
    channel: str,
    computer: str,
    provider: str,
    event_data: dict[str, str],
) -> str:
    """Compose the human-readable event text.

    A map hit wins over the built-in table: the corpus is scoped by channel *and*
    provider, whereas the built-in table is keyed by event id alone.
    """
    if map_result:
        # Every shipped property is in _MAP_PROPERTY_ORDER (asserted at vendor time and in
        # TestMapsBlob), so a property outside it can only come from a future corpus — it
        # is appended rather than dropped so a re-vendor cannot silently lose text.
        parts = [map_result[p] for p in _MAP_PROPERTY_ORDER if map_result.get(p)]
        extra = [v for k, v in map_result.items() if k not in _MAP_PROPERTY_ORDER and v]
        rendered = ", ".join(parts + extra)
        if rendered:
            return " ".join(rendered.split())

    mapped = _EVENT_MAP.get(event_id) if event_id is not None else None
    # The built-in table is keyed by event id alone, so it is only trustworthy on the
    # channel it was written for — other channels reuse ids like 1102 and 1000.
    if mapped and mapped[2] and channel.strip().lower() == "security":
        context = _Defaulting(computer=computer)
        context.update(event_data)
        rendered = mapped[2].format_map(context).strip()
        if rendered:
            return " ".join(rendered.split())

    return (
        f"EventID {event_id if event_id is not None else 'unknown'} "
        f"({provider or 'unknown provider'}) on {computer or 'unknown host'}"
    )


def build_row(root: ET.Element, no_maps: bool = False) -> dict[str, Any]:
    """Turn one parsed record into the converter's row dict."""
    system = _extract_system(root)
    event_data = _extract_event_data(root)

    attributes: dict[str, str] = dict(system)
    for key, value in event_data.items():
        safe = _safe_attr_key(key)
        # System spellings stay authoritative: a record whose EventData carries a
        # field called Channel must not be able to rewrite the real one.
        attributes[f"EventData_{safe}" if safe in system else safe] = value

    event_id = _safe_int(system.get("EventID"))
    channel = system.get("Channel", "")
    provider = system.get("Provider_Name", "")
    computer = system.get("Computer", "")

    map_result: dict[str, str] = {}
    if not no_maps and event_id is not None:
        mapping = _lookup_map(channel, provider, str(event_id))
        if mapping is not None:
            map_result = _eval_map(root, mapping)
            if mapping.get("d"):
                attributes["MapDescription"] = str(mapping["d"])
            for prop, value in map_result.items():
                attributes[f"Map{prop}"] = value

    src_ip = normalize_ip(event_data.get("IpAddress"))
    if src_ip:
        attributes["src_ip"] = src_ip
    src_port = _safe_int(event_data.get("IpPort"))
    if src_port is not None:
        attributes["src_port"] = str(src_port)
    if computer:
        attributes["host"] = computer
    user = event_data.get("TargetUserName") or event_data.get("SubjectUserName")
    if user:
        attributes["user"] = user

    timestamp = _parse_system_time(system.get("TimeCreated_SystemTime", ""))
    artifact, timestamp_desc = _artifact_for(channel, event_id)

    return {
        "message": _build_message(map_result, event_id, channel, computer, provider, event_data),
        "timestamp": _truncate_ms(timestamp),
        "timestamp_desc": timestamp_desc,
        "artifact": artifact,
        "artifact_long": f"windows:evtx:{channel}" if channel else "windows:evtx",
        "attributes": attributes,
    }


# ---------------------------------------------------------------------------
# Input discovery
# ---------------------------------------------------------------------------


def _looks_like_text_export(head: bytes) -> bool:
    """True when the leading bytes are XML or JSON rather than an EVTX container."""
    stripped = head.lstrip()
    return stripped[:5] in (b"<?xml", b"<Even") or stripped[:1] == b"{"


def _reject_text_export(path: Path, head: bytes) -> None:
    """Fail loudly when handed a text export instead of a binary .evtx."""
    if _looks_like_text_export(head):
        raise SystemExit(
            f"error: {path.name} is a text export, not a binary .evtx container.\n"
            "Use evtx2timesketch.py for wevtutil XML and evtx_dump XML/JSONL exports."
        )


def find_evtx_files(input_path: str) -> list[Path]:
    """Resolve the input into a sorted list of binary .evtx files.

    A directory is triage output: one stray file (a text export saved under the wrong
    extension, a zero-byte placeholder) is reported and skipped rather than aborting the
    whole collection. A single named file is a deliberate choice, so it still fails hard.
    """
    path = Path(input_path)
    if path.is_file():
        with path.open("rb") as fh:
            head = fh.read(8)
        _reject_text_export(path, head)
        if head != _EVTX_MAGIC:
            raise SystemExit(f"error: not a binary .evtx file (bad magic): {path}")
        return [path]
    if path.is_dir():
        found = sorted({p for p in path.rglob("*") if p.is_file() and p.suffix.lower() == ".evtx"})
        if not found:
            raise SystemExit(f"error: no .evtx files found in {input_path}")
        files = []
        for candidate in found:
            with candidate.open("rb") as fh:
                head = fh.read(8)
            if head != _EVTX_MAGIC:
                kind = (
                    "a text export, not a binary .evtx container (use evtx2timesketch.py)"
                    if _looks_like_text_export(head)
                    else "not a binary .evtx file (bad magic)"
                )
                sys.stderr.write(f"warning: skipping {candidate}: {kind}\n")
                continue
            files.append(candidate)
        if not files:
            raise SystemExit(
                f"error: no binary .evtx files found in {input_path} — every candidate was "
                "skipped. For wevtutil XML and evtx_dump XML/JSONL exports use "
                "evtx2timesketch.py."
            )
        return files
    raise SystemExit(f"error: input path not found: {input_path}")


def hash_file(path: Path) -> tuple[str, int]:
    """Return the streaming sha256 hex digest and size of ``path``."""
    digest = hashlib.sha256()
    size = 0
    with open(path, "rb") as fh:
        while chunk := fh.read(1024 * 1024):
            digest.update(chunk)
            size += len(chunk)
    return digest.hexdigest(), size


# ---------------------------------------------------------------------------
# Row batching / Parquet writing
# ---------------------------------------------------------------------------

BATCH_ROWS = 50_000
# Default cap on parallel workers; each worker memory-maps one input file and
# holds its parsed rows, so high core counts multiply peak RAM.
DEFAULT_MAX_WORKERS = int(os.environ.get("EVTX2VESTIGO_DEFAULT_WORKERS", 4))


class _BatchBuffer:
    """Columnar row buffer flushed to a ParquetWriter as record batches."""

    def __init__(self, writer: pq.ParquetWriter) -> None:
        self._writer = writer
        self._columns: dict[str, list[Any]] = {name: [] for name in PARQUET_EVENT_SCHEMA.names}
        self.rows_written = 0

    def append(
        self,
        source_file: str,
        file_hash: str,
        byte_offset: int,
        content_hash: str,
        row: dict[str, Any],
    ) -> None:
        cols = self._columns
        cols["source_file"].append(source_file)
        cols["file_hash"].append(file_hash)
        cols["byte_offset"].append(byte_offset)
        cols["content_hash"].append(content_hash)
        cols["message"].append(row["message"])
        cols["timestamp"].append(row["timestamp"])
        cols["timestamp_desc"].append(row["timestamp_desc"])
        cols["artifact"].append(row["artifact"])
        cols["artifact_long"].append(row["artifact_long"])
        cols["display_name"].append("")
        cols["tags"].append([])
        cols["attributes"].append(
            {k: str(v) for k, v in row["attributes"].items() if v is not None and str(v) != ""}
        )
        if len(cols["source_file"]) >= BATCH_ROWS:
            self.flush()

    def write_batch(self, batch: pa.RecordBatch) -> None:
        self._writer.write_batch(batch)
        self.rows_written += batch.num_rows

    def flush(self) -> None:
        if not self._columns["source_file"]:
            return
        batch = pa.RecordBatch.from_pydict(self._columns, schema=PARQUET_EVENT_SCHEMA)
        self.write_batch(batch)
        self._columns = {name: [] for name in PARQUET_EVENT_SCHEMA.names}


def _parse_since_until(value: str | None) -> datetime.datetime | None:
    """Parse an ISO 8601 ``--since``/``--until`` value to a UTC-aware datetime."""
    if not value:
        return None
    dt = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.UTC)
    return dt.astimezone(datetime.UTC)


class _FileCounts:
    """Per-file parse tallies carried into the footer metadata."""

    def __init__(self) -> None:
        self.parsed = 0
        self.skipped = 0
        self.skipped_by_time = 0
        self.offset_fallback = 0
        self.chunk_errors = 0
        self.sanitized = 0
        self.scan_note = ""

    def as_tuple(self) -> tuple[int, int, int, int, int, int, str]:
        return (
            self.parsed,
            self.skipped,
            self.skipped_by_time,
            self.offset_fallback,
            self.chunk_errors,
            self.sanitized,
            self.scan_note,
        )


def _convert_evtx(
    data: Any,
    source_file: str,
    file_hash: str,
    buffer: _BatchBuffer,
    since_dt: datetime.datetime | None = None,
    until_dt: datetime.datetime | None = None,
    no_maps: bool = False,
) -> _FileCounts:
    """Parse one memory-mapped .evtx image into the buffer."""
    counts = _FileCounts()
    stats = _ChunkScanStats()

    for blob, offsets in _iter_chunks(data, stats):
        try:
            records = PyEvtxParser(io.BytesIO(blob)).records()
        except Exception:  # noqa: BLE001 - parser raises bare RuntimeError
            counts.chunk_errors += 1
            continue
        while True:
            try:
                record = next(records)
            except StopIteration:
                break
            except Exception:  # noqa: BLE001 - a damaged chunk ends here, others go on
                counts.chunk_errors += 1
                break

            sanitized = False
            try:
                root = ET.fromstring(record["data"])
            except ET.ParseError:
                # Retry with XML-illegal control characters replaced by U+FFFD rather
                # than dropping a real event. Matches how the CSV/JSONL ingest path
                # handles undecodable bytes: the payload text becomes valid, the raw
                # record on disk is untouched, and the row says it was rewritten.
                cleaned = _RE_INVALID_XML_CHARS.sub("�", record["data"])
                try:
                    root = ET.fromstring(cleaned)
                except ET.ParseError:
                    counts.skipped += 1
                    continue
                sanitized = True
                counts.sanitized += 1

            row = build_row(root, no_maps=no_maps)
            if sanitized:
                row["attributes"]["xml_sanitized"] = "1"
            if row["timestamp"] is None:
                # Fall back to the record header's written time, and say so on the row.
                fallback = _truncate_ms(_parse_record_timestamp(str(record.get("timestamp", ""))))
                if fallback is not None:
                    row["timestamp"] = fallback
                    row["attributes"]["timestamp_basis"] = "record_header"

            ts = row["timestamp"]
            if ts is not None:
                if since_dt is not None and ts < since_dt:
                    counts.skipped_by_time += 1
                    continue
                if until_dt is not None and ts > until_dt:
                    counts.skipped_by_time += 1
                    continue
            # ts is None (unparseable/missing) → keep, matching upstream behavior.

            record_id = int(record["event_record_id"])
            # The record *header's* id is the key the offset scan joins on, and it can
            # legitimately differ from the <EventRecordID> element in the payload (an
            # extracted or re-chunked log renumbers one but not the other). Both are
            # kept so the offset is explainable from the row alone.
            row["attributes"]["evtx_record_id"] = str(record_id)
            # Only this chunk's offsets are consulted: a record id duplicated in another
            # chunk must not resolve to that chunk's record.
            located = offsets.get(record_id)
            if located is not None:
                offset, size = located
                content_hash = hashlib.sha256(bytes(data[offset : offset + size])).hexdigest()
                row["attributes"]["record_size"] = str(size)
            else:
                # No scanned offset: keep the row addressable by record id rather than
                # collapsing every such row onto offset 0, which would collide in the
                # server's event-identity derivation.
                offset = record_id
                content_hash = hashlib.sha256(record["data"].encode("utf-8")).hexdigest()
                row["attributes"]["content_hash_basis"] = "rendered_xml"
                counts.offset_fallback += 1

            buffer.append(source_file, file_hash, offset, content_hash, row)
            counts.parsed += 1
    counts.scan_note = stats.note()
    return counts


@contextlib.contextmanager
def _mapped(path: Path) -> Any:
    """Memory-map a file read-only so record slicing stays O(1) on multi-GB logs."""
    with open(path, "rb") as handle:
        if os.fstat(handle.fileno()).st_size == 0:
            # mmap rejects an empty file; an empty .evtx simply has no records.
            yield b""
            return
        with mmap.mmap(handle.fileno(), 0, access=mmap.ACCESS_READ) as mapping:
            yield mapping


def _parse_file(
    path_str: str,
    file_hash: str,
    since_dt: datetime.datetime | None = None,
    until_dt: datetime.datetime | None = None,
    no_maps: bool = False,
) -> tuple[bytes, tuple[int, int, int, int, int, int, str]]:
    """Worker: parse one .evtx file, return Arrow IPC bytes + counts."""
    sink = io.BytesIO()
    writer_ipc = pa.ipc.new_stream(sink, PARQUET_EVENT_SCHEMA)

    class _IpcBuffer(_BatchBuffer):
        def __init__(self) -> None:
            self._columns = {name: [] for name in PARQUET_EVENT_SCHEMA.names}
            self.rows_written = 0

        def write_batch(self, batch: pa.RecordBatch) -> None:
            writer_ipc.write_batch(batch)
            self.rows_written += batch.num_rows

    path = Path(path_str)
    buffer = _IpcBuffer()
    with _mapped(path) as data:
        counts = _convert_evtx(
            data,
            path.name,
            file_hash,
            buffer,
            since_dt=since_dt,
            until_dt=until_dt,
            no_maps=no_maps,
        )
    buffer.flush()
    writer_ipc.close()
    return sink.getvalue(), counts.as_tuple()


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------


def _available_ram_bytes() -> int | None:
    """Best-effort available RAM in bytes (Linux MemAvailable, else total)."""
    try:
        with open("/proc/meminfo", "rb") as fh:
            for raw in fh:
                line = raw.decode("ascii", errors="replace")
                if line.startswith("MemAvailable:"):
                    return int(line.split()[1]) * 1024
    except (OSError, ValueError, IndexError):
        pass
    try:
        return os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES")
    except (ValueError, AttributeError, OSError):
        return None


# ---------------------------------------------------------------------------
# Output splitting (ported from the 2timesketch converter suite's --split)
# ---------------------------------------------------------------------------

_RE_SPLIT_SIZE = re.compile(r"^(\d+)\s*([KMG])(?:I?B)?$", re.IGNORECASE)

# Upper bound on the row-batch granularity when rotating parts by size; the
# actual batch is scaled down for small size limits (see split_parquet).
_SPLIT_SIZE_BATCH_ROWS = 8192


def parse_split_spec(value: str) -> tuple[str, int]:
    """Parse a ``--split`` specification.

    Returns ``("parts", n)`` for a bare integer (split into ``n`` parts with
    an equal number of rows) or ``("size", nbytes)`` for a size specification
    such as ``"512K"``, ``"4M"``, or ``"1GiB"`` (suffixes are KiB/MiB/GiB,
    i.e. 1024-based).
    """
    text = value.strip()
    if text.isdigit():
        n = int(text)
        if n < 1:
            raise SystemExit(
                f"error: invalid --split value {value!r}: number of parts must be at least 1"
            )
        return ("parts", n)
    m = _RE_SPLIT_SIZE.match(text)
    if m:
        amount = int(m.group(1))
        if amount < 1:
            raise SystemExit(f"error: invalid --split value {value!r}: size must be at least 1")
        factor = {"K": 1024, "M": 1024**2, "G": 1024**3}[m.group(2).upper()]
        return ("size", amount * factor)
    raise SystemExit(
        f"error: invalid --split value {value!r}: use N (number of parts) or "
        "NK/NM/NG (part size in KiB/MiB/GiB, e.g. 4M)"
    )


def _part_path(output: str, index: int) -> Path:
    """Return the output path for part ``index`` (1-based)."""
    out = Path(output)
    return out.with_name(f"{out.stem}.part{index:03d}{out.suffix}")


def split_parquet(src: Path, output: str, spec: tuple[str, int], verbose: bool) -> list[Path]:
    """Repartition the single-file conversion at ``src`` into part files.

    ``("parts", n)`` distributes the rows into at most ``n`` parts of
    ``ceil(total / n)`` rows each; ``("size", nbytes)`` rotates to a new part
    once the current one reaches ``nbytes``, checked at row-batch granularity
    so a part may overshoot by up to one batch. Rows keep their original
    order, are never duplicated across parts, and every part carries the full
    interchange schema and provenance metadata, so each part is independently
    ingestible.
    """
    mode, amount = spec
    pf = pq.ParquetFile(src)
    schema = pf.schema_arrow
    # Carry footer key-value metadata added after the write loop (e.g.
    # vestigo.row_counts via add_key_value_metadata) into every part, so each
    # part keeps the full provenance. schema_arrow.metadata only holds keys set
    # at writer-open time; the rest live in the file's FileMetaData KV.
    extra = {
        k: v
        for k, v in (pf.metadata.metadata or {}).items()
        if k != b"ARROW:schema" and k not in (schema.metadata or {})
    }
    if extra:
        merged = dict(schema.metadata or {})
        merged.update(extra)
        schema = schema.with_metadata(merged)
    total = pf.metadata.num_rows
    if mode == "parts":
        rows_per_part = -(-total // amount) if total else 0
        batch_rows = max(1, min(BATCH_ROWS, rows_per_part or 1))
    else:
        rows_per_part = 0
        # The batch is the rotation granularity (a part may overshoot the
        # limit by up to one batch), so scale it to the limit; the 128 B/row
        # divisor keeps the overshoot small even for well-compressing rows.
        batch_rows = max(64, min(_SPLIT_SIZE_BATCH_ROWS, amount // 128))

    parts: list[Path] = []
    writer: pq.ParquetWriter | None = None
    part_rows = 0

    def open_next() -> pq.ParquetWriter:
        nonlocal writer, part_rows
        if writer is not None:
            writer.close()
        path = _part_path(output, len(parts) + 1)
        parts.append(path)
        part_rows = 0
        writer = pq.ParquetWriter(str(path), schema, compression="zstd")
        return writer

    try:
        for batch in pf.iter_batches(batch_size=batch_rows):
            while batch.num_rows:
                if (
                    writer is None
                    or (mode == "parts" and part_rows >= rows_per_part)
                    or (mode == "size" and part_rows > 0 and parts[-1].stat().st_size >= amount)
                ):
                    open_next()
                take = batch.num_rows
                if mode == "parts":
                    take = min(take, rows_per_part - part_rows)
                writer.write_batch(batch.slice(0, take))
                part_rows += take
                batch = batch.slice(take)
        if writer is None:
            # Zero rows: still produce a first (empty, schema-only) part.
            open_next()
    finally:
        if writer is not None:
            writer.close()
    if verbose:
        for path in parts:
            sys.stderr.write(f"  wrote {path}\n")
    return parts


def convert(
    input_path: str,
    output: str,
    workers: int,
    verbose: bool,
    split: str | None = None,
    since: str | None = None,
    until: str | None = None,
    no_maps: bool = False,
) -> int:
    """Convert the .evtx files at ``input_path`` into ``output`` (.parquet)."""
    if not output.lower().endswith(".parquet"):
        raise SystemExit(
            f"error: output path must end with .parquet (got: {output}) — the "
            "Vestigo server detects the ingest parser strictly by file extension."
        )

    since_dt = _parse_since_until(since)
    until_dt = _parse_since_until(until)

    split_spec = parse_split_spec(split) if split else None
    write_target = output if split_spec is None else f"{output}.tmp"

    files = find_evtx_files(input_path)

    if verbose:
        sys.stderr.write(f"hashing {len(files)} input file(s)...\n")
    provenance = []
    hashes: dict[Path, str] = {}
    for path in files:
        digest, size = hash_file(path)
        hashes[path] = digest
        stat = path.stat()
        provenance.append(
            {
                "name": path.name,
                "sha256": digest,
                "size_bytes": size,
                "path": str(path.resolve()),
                "mtime": datetime.datetime.fromtimestamp(stat.st_mtime, datetime.UTC).isoformat(),
            }
        )

    metadata = {
        META_FORMAT_VERSION: FORMAT_VERSION,
        META_CONVERTER_NAME: CONVERTER_NAME,
        META_CONVERTER_VERSION: CONVERTER_VERSION,
        META_ORIGINAL_FILES: json.dumps(provenance, sort_keys=True),
        META_CONVERTED_AT: datetime.datetime.now(datetime.UTC).isoformat(),
        META_TIMEZONE_ASSUMPTION: (
            "EVTX TimeCreated/@SystemTime is UTC; sub-millisecond precision is truncated to "
            "the interchange schema's millisecond resolution (the full-precision value is "
            "retained verbatim in the TimeCreated_SystemTime attribute)"
        ),
    }

    parsed_total = 0
    skipped_total = 0
    skipped_by_time_total = 0
    offset_fallback_total = 0
    chunk_errors_total = 0
    sanitized_total = 0
    scan_notes: dict[str, str] = {}

    def _tally(path_name: str, counts: tuple[int, int, int, int, int, int, str]) -> None:
        nonlocal parsed_total, skipped_total, skipped_by_time_total
        nonlocal offset_fallback_total, chunk_errors_total, sanitized_total
        parsed, skipped, by_time, fallback, chunk_errors, sanitized, note = counts
        if parsed == 0 and not by_time:
            # Never silent: a file that contributed nothing is either damaged beyond the
            # chunk walk or not what it claims to be, and the run still exits 0 as long as
            # some other file parsed.
            sys.stderr.write(f"warning: {path_name} yielded no records ({note})\n")
        parsed_total += parsed
        skipped_total += skipped
        skipped_by_time_total += by_time
        offset_fallback_total += fallback
        chunk_errors_total += chunk_errors
        sanitized_total += sanitized
        scan_notes[path_name] = note

    schema = PARQUET_EVENT_SCHEMA.with_metadata(metadata)
    with pq.ParquetWriter(write_target, schema, compression="zstd") as writer:
        buffer = _BatchBuffer(writer)

        if workers > 1 and len(files) > 1:
            if verbose:
                sys.stderr.write(f"parsing {len(files)} file(s) across {workers} workers...\n")
            ram = _available_ram_bytes()
            largest = max(path.stat().st_size for path in files)
            # Rough per-worker estimate: the mapped file plus its rendered rows and
            # the Arrow IPC copy handed back to the parent.
            estimated = min(workers, len(files)) * largest * 6
            if ram and estimated > ram * 0.75:
                sys.stderr.write(
                    f"warning: {workers} workers on files up to "
                    f"{largest // (1024 * 1024)} MiB may need "
                    f"~{estimated // (1024 * 1024)} MiB RAM; "
                    f"~{ram // (1024 * 1024)} MiB available. Reduce -w if memory runs out.\n"
                )
            ctx = multiprocessing.get_context("spawn")
            with concurrent.futures.ProcessPoolExecutor(
                max_workers=workers, mp_context=ctx
            ) as pool:
                # Submit a bounded window and consume strictly in submit order:
                # rows land in the output in input-file order (forensic
                # requirement), and at most ~2*workers file results exist in
                # the parent at once, so finished-but-unwritten Arrow IPC
                # results cannot pile up and OOM the parent.
                file_iter = iter(files)
                pending: collections.deque = collections.deque()

                def _submit_next() -> None:
                    path = next(file_iter, None)
                    if path is None:
                        return
                    pending.append(
                        (
                            path.name,
                            pool.submit(
                                _parse_file,
                                str(path),
                                hashes[path],
                                since_dt,
                                until_dt,
                                no_maps,
                            ),
                        )
                    )

                for _ in range(workers * 2):
                    _submit_next()
                while pending:
                    name, future = pending.popleft()
                    ipc_bytes, counts = future.result()
                    _submit_next()
                    _tally(name, counts)
                    reader = pa.ipc.open_stream(ipc_bytes)
                    for batch in reader:
                        if batch.num_rows:
                            buffer.write_batch(batch)
        else:
            for path in files:
                if verbose:
                    sys.stderr.write(f"parsing {path}...\n")
                with _mapped(path) as data:
                    counts = _convert_evtx(
                        data,
                        path.name,
                        hashes[path],
                        buffer,
                        since_dt=since_dt,
                        until_dt=until_dt,
                        no_maps=no_maps,
                    )
                _tally(path.name, counts.as_tuple())

        buffer.flush()
        writer.add_key_value_metadata(
            {
                META_ROW_COUNTS: json.dumps(
                    {
                        "parsed": parsed_total,
                        "skipped_malformed": skipped_total,
                        "skipped_by_time": skipped_by_time_total,
                    }
                ),
                META_PARSE_DECISIONS: json.dumps(
                    {
                        "since": since,
                        "until": until,
                        "maps": "disabled" if no_maps else "evtxecmd",
                        "evtxecmd_maps_commit": "" if no_maps else MAPS_SOURCE_COMMIT,
                        "byte_offset": "record offset within the original .evtx",
                        "byte_offset_fallback_rows": offset_fallback_total,
                        "content_hash": "sha256 of the raw record bytes",
                        "chunk_errors": chunk_errors_total,
                        "xml_sanitized_rows": sanitized_total,
                        "chunk_scan": scan_notes,
                    },
                    sort_keys=True,
                ),
            }
        )

    time_note = f", {skipped_by_time_total} outside --since/--until" if (since or until) else ""
    damage_note = f", {chunk_errors_total} damaged chunk(s) skipped" if chunk_errors_total else ""
    if split_spec is not None:
        try:
            parts = split_parquet(Path(write_target), output, split_spec, verbose)
        finally:
            Path(write_target).unlink(missing_ok=True)
        sys.stderr.write(
            f"{CONVERTER_NAME}: wrote {parsed_total} events to {len(parts)} part "
            f"file(s) [{parts[0].name} .. {parts[-1].name}] "
            f"({skipped_total} unparseable records skipped{time_note}{damage_note})\n"
        )
    else:
        sys.stderr.write(
            f"{CONVERTER_NAME}: wrote {parsed_total} events to {output} "
            f"({skipped_total} unparseable records skipped{time_note}{damage_note})\n"
        )
    return 0 if parsed_total > 0 else 1


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Convert binary Windows Event Log (.evtx) files (file or directory) "
            "to a Vestigo Parquet file for direct upload."
        )
    )
    parser.add_argument("-i", "--input", required=True, help=".evtx file or directory")
    parser.add_argument("-o", "--output", required=True, help="output .parquet path")
    parser.add_argument(
        "-w",
        "--workers",
        type=int,
        default=min(getattr(os, "process_cpu_count", os.cpu_count)() or 4, DEFAULT_MAX_WORKERS),
        help="parallel parser processes across input files (default: min(CPU count, %(default)s))",
    )
    parser.add_argument(
        "--split",
        metavar="N|SIZE",
        help="split the output into multiple .parquet files: N = N parts with "
        "an equal number of rows (e.g. 4); SIZE = rotate to a new part once "
        "it reaches SIZE, with a K/M/G suffix meaning KiB/MiB/GiB (e.g. "
        "512M). Parts are named <name>.partNNN.parquet.",
    )
    parser.add_argument(
        "--since",
        help="Only records at or after this ISO 8601 timestamp "
        "(e.g. 2026-07-01T00:00:00Z). Rows with no parseable timestamp are kept.",
    )
    parser.add_argument(
        "--until",
        help="Only records at or before this ISO 8601 timestamp "
        "(e.g. 2026-07-01T23:59:59Z). Rows with no parseable timestamp are kept.",
    )
    parser.add_argument(
        "--no-maps",
        action="store_true",
        help="skip the embedded EvtxECmd map corpus: emit only the fields literally "
        "present in the record, with a generic message.",
    )
    parser.add_argument("-v", "--verbose", action="store_true", help="progress on stderr")
    args = parser.parse_args()
    return convert(
        args.input,
        args.output,
        max(1, args.workers),
        args.verbose,
        split=args.split,
        since=args.since,
        until=args.until,
        no_maps=args.no_maps,
    )


if __name__ == "__main__":
    sys.exit(main())
